<script lang="ts">
  import type {Database,DatabaseViewConfig,Page} from "@/features/notion-ui/variants/database/types"; import {numeric,propValue} from "../../lib/view-core";
  let {db,view,rows,onOpenRow}= $props<{db:Database;view:DatabaseViewConfig;rows:Page[];onOpenRow?:(id:string)=>void}>(); let latProp=$derived(db.properties.find(p=>p.id===view.mapLatProp)??db.properties.find(p=>/lat/i.test(p.name))),lngProp=$derived(db.properties.find(p=>p.id===view.mapLngProp)??db.properties.find(p=>/(lng|lon)/i.test(p.name))); let pins=$derived(rows.flatMap(row=>{const lat=latProp?numeric(propValue(row,latProp)):null,lng=lngProp?numeric(propValue(row,lngProp)):null;return lat==null||lng==null?[]:[{row,lat,lng}]}));
  const x=(lng:number)=>(lng+180)/360*100, y=(lat:number)=>(90-lat)/180*100;
</script>
<div class="grid gap-3 p-3 lg:grid-cols-[1fr_240px]"><div class="relative min-h-80 overflow-hidden rounded-lg border bg-muted/20"><div class="absolute inset-0 opacity-30" style="background-image:linear-gradient(to right,currentColor 1px,transparent 1px),linear-gradient(to bottom,currentColor 1px,transparent 1px);background-size:12.5% 25%"></div>{#each pins as pin (pin.row.id)}<button class="absolute size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-background bg-foreground shadow" style={`left:${x(pin.lng)}%;top:${y(pin.lat)}%`} title={pin.row.title} aria-label={pin.row.title} onclick={()=>onOpenRow?.(pin.row.id)}></button>{/each}{#if !latProp||!lngProp}<p class="absolute inset-0 grid place-items-center text-xs text-muted-foreground">Configure latitude and longitude properties.</p>{/if}</div>{#if view.mapShowList!==false}<div class="space-y-1">{#each pins as pin (pin.row.id)}<button class="w-full rounded border px-2 py-2 text-left text-xs hover:bg-muted" onclick={()=>onOpenRow?.(pin.row.id)}><strong class="block truncate">{pin.row.title||"Untitled"}</strong><span class="text-muted-foreground">{pin.lat.toFixed(4)}, {pin.lng.toFixed(4)}</span></button>{/each}</div>{/if}</div>
